def process(votes_data):
    df = votes_data.copy()
    df['state_classification'] = df['percent_democrat'].apply(
        lambda x: 'Democratic' if x > 50 else 'Republican'
    )
    return df[['state', 'state_classification', 'percent_democrat']]

def process(fires_data, classify_states) -> pd.DataFrame:
    merged = fires_data.merge(classify_states, left_on='State', right_on='state', how='inner')
    return merged[['State', 'Total Fires', 'state_classification']]
